function atsCtrl($scope,mS,tS,FileSaver,Blob){"use strict";function getActualMonth(){let actualDate;return(new Date).getMonth()+1}function initialLoad(){try{mS.getData("get","/Ats/GetPeriods").then(response=>{$scope.years=response[0],$scope.months=response[1],$scope.yearSelected=response[0][0];for(const element of $scope.months)getActualMonth()===element.month&&($scope.monthSelected=element);6!==getActualMonth()&&12!=getActualMonth()||declarationType()})}catch(error){console.log(error)}}function getAts(){try{let json={semianual:$scope.semiannual,year:Number($scope.yearSelected.year),month:Number($scope.monthSelected.month)};mS.getFile("get","/Ats/Get?json="+JSON.stringify(json)).then(response=>{if(0!=response.id){if(response.data.size>0){let serverData=new Blob([response.data],{type:response.headers()["content-type"]}),fileName=response.headers()["content-disposition"].split(";")[1].split("=")[1];FileSaver.saveAs(serverData,fileName)}}else tS.toastr("warning",response.message)})}catch(error){console.log(error)}}function downloadXml(){window.open("/AtsVenta/getXmlSales?year="+$scope.year.year+"&month="+$scope.month.codigo,"_blank")}$scope.getAts=getAts,$scope.downloadXml=downloadXml,$scope.initialLoad=initialLoad,initialLoad(),$scope.semiannual=!1,$scope.showSemiAnual=!1,$scope.declarationType=function(){if($scope.yearSelected.year>=2020&&(6==$scope.monthSelected.month||12==$scope.monthSelected.month))return $scope.semiannual=!1,void($scope.showSemiAnual=!0);$scope.semiannual=!1}}angular.module("acontPlusApp").controller("atsCtrl",atsCtrl),atsCtrl.$inject=["$scope","mainService","toastService","FileSaver","Blob"];